import{_ as o,o as t,c as l,a2 as c}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph User + Dev Monthly - July 2025","description":"","frontmatter":{"title":"Ceph User + Dev Monthly - July 2025","date":"2025-07-16T00:00:00.000Z","updated":"2025-07-17T00:00:00.000Z","tags":["Ceph社区","CephCon","Ceph用户参与","CephCon提案","CephCon活动"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_User_+_Dev_Monthly_-_July_2025.md","filePath":"posts/2025/Ceph_User_+_Dev_Monthly_-_July_2025.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Ceph_User_+_Dev_Monthly_-_July_2025.md"};function d(n,e,i,s,p,a){return t(),l("div",null,[...e[0]||(e[0]=[c('<h3 id="ceph-用户-开发者月度会议-七月-2025" tabindex="-1">Ceph 用户 + 开发者月度会议 - 七月 2025 <a class="header-anchor" href="#ceph-用户-开发者月度会议-七月-2025" aria-label="Permalink to &quot;Ceph 用户 + 开发者月度会议 - 七月 2025&quot;">​</a></h3><p>本次会议主要讨论了 Ceph 社区活动、用户参与策略以及一些技术议题。</p><p><strong>社区活动（CephCon）</strong>:</p><ul><li><strong>CephCon 2023 注册</strong>：会议将于温哥华举办，Laura 提供了注册链接，鼓励社区成员参与。</li><li><strong>提案征集（CFP）截止</strong>：CFP 提交截止时间为当天 23:59（太平洋时间），Anthony 强调需要更多用户故事，包括 Ceph 在实际场景中的应用案例、解决技术问题的经验分享、改进建议或痛点反馈等。</li></ul><p><strong>Ceph 用户参与策略</strong>:</p><ul><li>Anthony 分享了三步计划： <ol><li><strong>“Ceph 在您组织的状态”调查</strong>：收集用户反馈，用于改进社区策略。</li><li><strong>Ceph 愿景板</strong>：整理 Ceph 的发展历程、现状和未来方向，需社区成员贡献案例。</li><li><strong>CephCon 用户互动</strong>：计划通过博客/视频形式分享用户故事，并现场采访参会者。</li></ol></li><li>行动项：填写调查表并积极参与 CephCon 的内容贡献和讨论。</li></ul><p><strong>技术议题</strong>:</p><ul><li><strong>容器化 Ceph 的补丁构建问题</strong>：当前 <code>build-container</code> 脚本仅支持从官方仓库拉取包，无法使用本地构建的补丁包。讨论建议提交 Tracker Ticket，评估通过 Shaman 构建临时包的可行性。</li><li><strong>RGW 的 S3 API 兼容性回归问题</strong>：测试发现 Reef/Squid 版本的 RGW 在部分 S3 API 行为上比 Quincy 版本更不符合 AWS S3 规范。后续行动为提交 Tracker Ticket，附详细测试对比，RGW 团队跟进 Issue。</li></ul><p><strong>决议与行动计划</strong>:</p><ul><li>所有成员尽快提交 CephCon 提案。</li><li>参与用户调查，推动故事分享计划。</li><li>提交 Tracker Ticket，跟进技术问题。</li><li>下月例会将继续讨论进展。</li></ul><p><strong>关键词保留</strong>:</p><ul><li><code>OSD</code>, <code>MON</code>, <code>MDS</code>, <code>PG</code>, <code>RADOS</code>, <code>librados</code>, <code>CephFS</code>, <code>RBD</code>, <code>RGW</code></li><li><code>Object Storage</code>, <code>Block Storage</code>, <code>File System Storage</code></li><li><code>CRUSH Algorithm</code>, <code>Erasure Coding</code>, <code>Replication</code>, <code>BlueStore</code>, <code>RocksDB</code></li><li><code>Kubernetes</code>, <code>AWS S3 API</code>, <code>iSCSI</code>, <code>NFS</code>, <code>CIFS</code></li></ul>',12)])])}const C=o(r,[["render",d]]);export{h as __pageData,C as default};
